 public const string HelpRu="Перенос на маркер/квест выполняется очередью: рядом — прямой поиск, далеко — короткие этапы по проверенной земле для подгрузки района. Статус виден внизу; в Движении есть просмотр и отмена. Нужно быть пешком вне сцены, с выключенным noclip; карта ставит перенос на паузу. Дождитесь завершения или отмените перед сохранением. При отсутствии опоры остановится на последней площадке. Стелс: Полиция игнорирует Ви — отдельный переключатель без общей невидимости. Снимает текущий розыск, блокирует новый и полицейские реакции на Ви, выстрелы и атаки, включая транспорт и гранаты. Обычные враги не меняются. Выключение возвращает обычное поведение; прежние звёзды не восстанавливаются. Сюжетные блокировки не переписываются; сцены могут задавать реакцию напрямую. 0.3.19: Транспорт → Редактор транспорта: машины и мотоциклы. Настраиваются скорость вперёд/назад, целевой разгон и торможение, поворот, подавление заноса и подскока. Пресет Устойчиво: 250/40 км/ч, разгон/торможение 2 с, поворот 90, сцепление 12, подскок 0. Постоянный прижим убран; помощь ограничена по ускорению, на высокой скорости поворот плавнее. Мотоциклы сохраняют штатный наклон; в воздухе и при трюках помощь приостанавливается. В редакторе показан фактический статус. Поставить транспорт на колёса работает для текущего транспорта или выбранного взглядом в пределах 12 м, при скорости ниже 5 км/ч и свободном месте над загруженной поверхностью. Сюжетный транспорт и другой водитель исключены. После переворота помощь ждёт 1 с. Проверку физики и переворота в игре делает владелец. Неуязвимый личный транспорт дополнен восстановлением кузова/стёкол и подавлением разрушения деталей. Первый вход в личную машину ремонтирует её; ремонт не откатывается. Стелс: NPC не замечают Ви в приседе — отдельная функция; при выпрямлении отпускает, постоянный режим имеет приоритет. Движение: Рывки без перезарядки и лимита в воздухе; Сила рывка ×N 0,25–10, 1 — штатная. Повтор после окончания текущего движения. Мгновенный режим разрешает повторный Звуковой шок, сохраняя проверки типа цели/сюжета. Бесплатное улучшение исправлено для ресурсов риппера и нулевой стоимости интерфейса; после переключения обновите наведение или откройте меню заново. \r\n\r\n0.3.19: телепорты ищут соседнюю площадку и подходящий этаж. Для задания предпочитают 20 м, при препятствиях выбирают безопасное расстояние до 90 м; блинк ищет локально до 8 м и сохраняет предел дальности. Высота цели используется вместо высоты игрока. Если коллизии района полностью не загружены, перенос отклоняется. Включённые функции и успешно применённые временные параметры сохраняются автоматически в профиле Windows. При запуске сначала ожидается игрок, затем восстанавливаются параметры и переключатели; АВТО означает сохранённую функцию, ещё не подтверждённую игрой. Обычное закрытие выключает эффекты, сохраняя выбор для следующего запуска. Отключить всё / Ctrl+F12 очищает также сохранённые функции и параметры. Разовые действия, выдача предметов и изменения денег/уровня не повторяются. \r\n\r\n0.3.19: исправлена передача игрового контекста для настройки/чтения слотов, выбора ОС способности и открытия редактора внешности. Сначала закройте игровые меню, настройте слоты, затем откройте импланты заново.\r\n\r\nКиберимпланты → Слоты имплантов: выберите часть тела и общее число ячеек до 8. Кнопка «Два слота операционной системы» задаёт два слота для кибердеки вместе с Сандевистаном или Берсерком. Сначала закройте игровые меню, затем настройте и заново откройте импланты. Установка через риппера или «Установить вместе» в ItemSpawner; импланты должны быть в инвентаре. Кибердека остаётся источником скриптов, обычная кнопка ОС активирует выбранный Сандевистан/Берсерк. При нескольких ОС способностей переключайтесь кнопкой «Следующая ОС способности»; в режиме сканера обычная кнопка активирует разгон кибердеки. Одновременно используется одна активная ОС способности; программы берутся из первой установленной кибердеки. Число слотов сохраняется с персонажем. 0 возвращает штатное число, если удаляемые ячейки пусты. Оружие рук не расширяется; лимит ёмкости снимается отдельной функцией. Работа комбинаций ещё требует проверки владельцем.\r\n\r\nПерсонаж → Полный редактор внешности: откройте из обычной игры пешком, вне боя, диалога, транспорта, брейнданса и других меню; noclip должен быть выключен. Загружается текущая внешность Ви. Доступны косметические параметры создания персонажа включая лицо, кожу, волосы, татуировки, тип тела и голос, с учётом настроек цензуры. Смена типа тела и голоса может изменить связанные проверки отношений и реплик. При отмене исходные тело и голос возвращаются. Происхождение, атрибуты, очки и тип кампании защищены перед применением; квесты, инвентарь и развитие не редактируются. Сохранить применяет внешность штатным способом; Отмена отбрасывает изменения. Случайный облик не применяется при открытии. Изменение внешности сохраняется в обычном сохранении игры и не отменяется Ctrl+F12. Новая функция ещё требует проверки владельцем.\r\n\r\n0.3.17: в Киберимплантах добавлено Мгновенное сканирование для обычного мира и брейндансов. Наведите сканер на доступный объект: ожидание сокращается до следующего такта игры; завершение и результаты обрабатываются самой игрой. В брейндансе выберите правильный слой и момент записи. Функция не открывает заблокированные сюжетные улики и не сканирует всё вокруг. Длительность возвращается при смене цели, выключении и сбросе. Уже изученные объекты/улики не становятся неизученными. Проверка в игре ещё нужна.\r\n\r\nДиалоги: Реплики всех происхождений открывают дополнительные ответы кочевника, дитя улиц и корпората; Реплики без требований навыков пропускают проверки характеристик в ответах. Включайте до начала разговора; для уже открытого выбора может понадобиться заново открыть диалог. Проверяется само условие, а не только цвет строки. Происхождение и характеристики Ви не меняются. Реплики, которых нет в текущей сцене, сюжетные флаги и платные ответы не создаются. Последствия выбранного ответа остаются обычными и могут сохраниться.\r\n\r\n0.3.17: мгновенный режим убирает ожидание анимации подтверждения и блокировку устройств «цель под действием скрипта». Повтор нестакуемого эффекта перезапускает именно его; другие эффекты на цели не снимаются. Старые завершения отвлечения устройства игнорируются после нового применения. Отдельный Незаметный нетраннер убирает обнаружение и проценты отслеживания, блокирует запуск трассировки и прерывает текущую. Выключение разрешает последующие обычные трассировки. Зрение NPC и последствия видимого урона этим режимом не отключаются. Проверка в игре ещё нужна.\r\n\r\n0.3.17: для свободного нетраннинга включите Бесконечную RAM и Мгновенные скрипты без очереди в Киберимплантах. RAM убирает стоимость и нехватку памяти; новый режим применяет выбранные скрипты сразу, сохраняет разные эффекты на цели и снимает перезарядку. Сюжетные блокировки, иммунитеты и отсутствие нужного скрипта в кибердеке остаются. Повтор перезапускает выбранный нестакуемый эффект, остальные скрипты сохраняются. Уже идущая загрузка завершается штатным обработчиком; после выключения новые взломы снова используют обычную загрузку и очередь. Проверка в игре ещё нужна.\r\n\r\nНовые режимы устройств: включите перед обычным взломом турели или камеры. Удержание отключения блокирует автоматическое пробуждение; ручное включение и сюжетные команды имеют приоритет. Бессрочное дружественное управление останавливает реальный таймер, выключение продолжает остаток. Действует в текущей игровой сессии; после загрузки/выгрузки устройства может понадобиться повторный взлом. Игровая проверка владельцем ещё нужна.\r\n\r\nЭкспериментальная сборка для Steam 2.5 с Phantom Liberty. Проверены компиляция и локальные компоненты. Подключение порта 2.5 и игровые эффекты ещё не проверены. Версия 0.3.19. Локальный экспериментальный CET для 2.5: запуск и эффекты в игре ещё не проверены. Точность, отдача и магазин обрабатываются для обеих рук. Для непрерывных ударов включите «Бесконечная серия ударов» в категории боя; это отдельный ограничитель комбо, а не запас выносливости. При бесконечной выносливости HUD синхронизируется с реальным пулом и не становится почти прозрачным на 100%. Выносливость восстанавливается явным запросом к пулу; защита от обычных попаданий дополнена проверкой в обработчике урона. Диагностика здоровья и выносливости находится в «Выживании».\r\n\r\n«NPC не замечают Ви» отключает видимость для системы восприятия без оптического камуфляжа; блокирует также шум выстрелов и боевые угрозы. Прежний скрытый режим сохранён отдельно. «Остановить таймер выбора реплики» автоматически приостанавливает сцену на выборе с таймером; подтверждение ответа возобновляет время. Выключение функции и Ctrl+F12 также снимают паузу. Новые функции требуют проверки в игре.\r\n\r\nУстановка: README и Install.ps1. Игра должна быть закрыта при установке. Загрузите сохранение самостоятельно, затем откройте трейнер.\r\n\r\nКлавиши из исходного запроса сохранены. Категории и поиск находятся слева и над списком. Числовые параметры: ползунок для обычного диапазона, поле для точного ввода (шире ползунка) и кнопка «Стандарт» для сброса каждого параметра отдельно. Привязки меняются щелчком по клавише в строке функции или F2; Delete в окне ввода убирает привязку, Esc отменяет; работают только при активной игре. Для блинка и Сандевистана сначала включите функцию, затем нажмите кнопку вызова. MButton переключает режим чёрного заслона с пустыми руками; ЛКМ запускает жест и красный эффект DLC по нескольким целям: сначала под прицелом, затем ближайшие к направлению взгляда. Число целей (по умолчанию 5) и дальность (75 м) настраиваются; зажатая ЛКМ повторяет удар каждые 2 с. Включение режима не требует цели. Noclip задаёт скорость по камере без коррекции позиции: пробел/Ctrl вверх/вниз, Shift ×3.\r\n\r\nCtrl+F12 сбрасывает временные эффекты и параметры. Деньги, опыт, уровни, перки, выданные и восполненные предметы, открытые двери и игровое время могут остаться в сохранении. Отключение их не отменяет.\r\n\r\nАвтовзлом при открытии протокола сразу отмечает все программы выполненными и показывает штатный экран успеха. Выйдите обычной кнопкой протокола для выдачи наград. «Решить текущий протокол» делает то же для уже открытого меню. Заморозка таймера удерживает оставшееся время и полосу, без увеличения до часа. В ItemSpawner есть «Установить вместе» для уже полученных имплантов и ОС; дополнительные импланты снимаются сбросом. Оружие рук одновременно не устанавливается. Работа новых функций требует проверки в игре. Проверки ёмкости имплантов обходятся отдельно. В категории «Предметы» добавлены разблокировка рецептов, бесплатный крафт и бесплатное улучшение, включая импланты. Рецепты и результаты операций сохраняются. Ёмкость имплантов временно повышается до 10 000. «Без киберпсихоза / ярости» подавляет ярость Edgerunner и штраф перегрузки; отдельного счётчика психоза Ви в базовой игре нет.\r\n\r\nОграничения: расходники и материалы возвращаются также после продажи; квестовые предметы и деньги исключены. Сандевистан требует установленный имплант: «Бесконечный Сандевистан» снимает расход заряда, стоимость входа и перезарядку реального импланта, а «Сандевистан: мир замирает» почти останавливает время вокруг, пока Ви движется с обычной скоростью. Оба режима выключаются, если имплант снят. Способность Сойки работает с пустыми руками и штатной анимацией DLC; ЛКМ атакует, MButton включает и убирает режим. Оружейные слоты не меняются. Поиск целей и эффект требуют проверки в игре. Телепорт к квесту ставит примерно за 20 м до цели с проверкой поверхности и работает только при доступной загруженной позиции цели. Личный маркер удаляется после подтверждения прибытия.";
 public const string HelpEn="Waypoint/objective travel is queued: nearby direct search, distant grounded hops to load subsequent areas. Status appears below; Movement has status/cancel actions. Be on foot outside scenes with noclip disabled; the map pauses travel. Finish or cancel before saving. Missing support stops at the last landing. Stealth: Police ignore V is independent of global invisibility. Clears current heat and blocks new crime reports and police reactions to V, gunfire, attacks, driven vehicles and grenades. Other enemies remain unchanged. Disabling restores normal behavior, not previous stars. Quest locks are preserved; scripted scenes can set behavior directly. 0.3.19: Vehicles → Vehicle editor: cars and motorcycles. Controls forward/reverse speed, target acceleration/braking, turning, slide suppression and anti-bounce. Stable preset: 250/40 km/h, 2 s acceleration/braking, turn 90, grip 12, anti-bounce 0. Constant downforce removed; assistance uses acceleration bounds and softens turns at high speed. Motorcycles retain native lean; assistance pauses in the air and during stunts. Live controller status is displayed. Return vehicle to wheels works for your mounted vehicle or one looked at within 12 m, below 5 km/h, with loaded ground and upright clearance. Scene vehicles and other drivers are excluded. Assistance waits 1 s after recovery. Native physics and recovery still require owner gameplay checks. Personal vehicle protection now restores bodywork/glass and suppresses damaged-part visuals. First entry repairs the owned car; repairs persist. Stealth: Undetected by NPCs while crouched is separate; standing releases it while permanent undetection takes priority. Movement: Unlimited ground and air dashes; Dash strength ×N 0.25–10, 1 is native. Repeat after current movement ends. Instant quickhacks permit repeated Sonic Shock while keeping NPC-type/quest checks. Free upgrades fix ripperdoc resource costs and zero-cost UI; refresh hover or reopen the menu after switching. \r\n\r\n0.3.19: teleports search nearby surfaces and suitable levels. Quest teleport prefers 20 m and falls back to safe distances up to 90 m; blink searches locally up to 8 m and retains its range limit. Target elevation replaces player elevation. Fully unloaded collision still rejects teleportation. Enabled features and successfully applied temporary parameters are saved automatically in the Windows profile. On startup the trainer waits for the player, restores parameters, then toggles; AUTO means a saved feature not yet acknowledged by the game. Normal exit disables effects while keeping preferences for next time. Turn all off / Ctrl+F12 also clears saved features and parameters. One-time actions, item grants and money/level edits never replay. \r\n\r\n0.3.19: fixed game-context delivery for slot configuration/count queries, ability OS selection and opening the appearance editor. Close game menus, configure slots, then reopen cyberware.\r\n\r\nCyberware → Cyberware slots: select an area and a total count up to 8. Two operating system slots provides two slots for a cyberdeck with Sandevistan or Berserk. Close game menus before changing counts, then reopen cyberware. Install at a ripperdoc or with Install alongside in ItemSpawner; implants must be owned. The cyberdeck remains the quickhack source, while the normal OS button activates the selected Sandevistan/Berserk. With multiple ability operating systems, use Next ability operating system to select one; in scanner mode the normal button activates cyberdeck Overclock. One ability OS is active at a time; programs come from the first equipped cyberdeck. Counts persist with the character. 0 restores native count when removed slots are empty. Arm weapon slots are excluded; capacity limits use the separate feature. Combinations still require owner gameplay verification.\r\n\r\nCharacter → Full appearance editor: open during normal on-foot gameplay, outside combat, dialogue, vehicles, braindance and other menus; disable noclip first. Starts from V current appearance. Exposes character-creation cosmetic options including face, skin, hair, tattoos, body type and voice, subject to censorship settings. Changing body type or voice can affect related relationship and dialogue checks. Cancel restores the original body type and voice. Lifepath, attributes, points and campaign type are protected before applying; quests, inventory and progression are not edited. Save applies appearance through the native update flow; Cancel discards it. Opening never applies a random preset. Appearance changes persist in normal game saves and are not undone by Ctrl+F12. This new feature still requires owner gameplay verification.\r\n\r\n0.3.17: Instant scanning in Cyberware supports normal gameplay and braindance. Target an available scannable object: completion runs on the next game tick through the native scan pipeline. Braindance requires the correct layer and timeline moment. Locked quest clues and surrounding untargeted objects are not scanned. Original duration returns on target changes, disabling and reset. Completed scans/clues are not undone. Gameplay verification is still required.\r\n\r\nDialogues: All lifepath dialogue options unlocks extra Nomad, Streetkid and Corpo responses; Ignore dialogue skill requirements passes dialogue build/attribute checks. Enable before conversation; an existing choice may need reopening. The actual condition is passed, not just the UI color. V lifepath and attributes remain unchanged. No absent scene branches, quest flags or paid responses are created. Normal response consequences may persist in saves.\r\n\r\n0.3.17: instant mode bypasses the confirmation animation and the device target-already-quickhacked lock. Repeats restart only the selected nonstackable effect; other effects remain. Older distraction completions are ignored after a newer application. Separate Untraceable netrunner removes trace labels/percentages, prevents trace startup and cancels a current trace. Disabling permits future normal traces. NPC sight and reactions to visible damage remain separate. Gameplay verification is still required.\r\n\r\n0.3.17: enable Infinite RAM and Instant quickhacks without queues in Cyberware. RAM removes costs and insufficient-memory checks; the new mode applies selected quickhacks immediately, preserves different effects on a target and skips cooldowns. Quest locks, immunities and required equipped quickhacks remain. Repeats restart the selected nonstackable effect while preserving other hacks. An existing upload finishes via its normal handler; disabling restores normal uploads and queues for new hacks. Gameplay verification is still required.\r\n\r\nNew device modes: enable before a normal turret or camera quickhack. Keep devices switched off blocks automatic wake-up; manual activation and quest commands take priority. Indefinite friendly control freezes the real timer; disabling resumes remaining time. Applies to the current session; reloading/streaming may require another quickhack. Gameplay verification is still required.\r\n\r\nExperimental build for Steam 2.5 with Phantom Liberty. Compilation and local components have been checked. Connectivity and gameplay effects of the 2.5 port remain unverified. Version 0.3.19. Local experimental CET for 2.5: startup and gameplay effects remain unverified. Accuracy, recoil and magazines support both hands. For continuous melee enable Infinite melee combo in Combat; combo termination is separate from the stamina pool. Infinite stamina synchronizes HUD to the real pool and prevents the full bar from fading almost transparent. Stamina uses an explicit pool refill; ordinary hit protection is also enforced in the damage handler. Health and stamina diagnostics are in Survival.\r\n\r\nUndetected by NPCs disables the perception visibility component without optical camouflage; also blocks gunshot stimuli and combat threats. The original stealth mode remains separate. Freeze timed dialogue choices automatically pauses the scene during a timed choice; confirming a response resumes time. Disabling it and Ctrl+F12 also release the pause. These new features require gameplay verification.\r\n\r\nInstallation: README and Install.ps1. Close the game before installation. Load a save yourself, then open the trainer.\r\n\r\nRequested default shortcuts are preserved. Categories and search filter the list. Numeric parameters: a slider for the usual range, a field for exact input beyond it and a Default button that resets each parameter separately. Click the binding beside a feature or press F2 to edit it; Delete in the capture window unbinds and Esc cancels. Keyboard, middle mouse and side buttons are supported. Bindings only act while the game has focus. Enable blink or Sandevistan first, then use its activation button. MButton toggles empty-hand Blackwall mode; LMB plays the DLC gesture and red effect on several targets: the one under the crosshair first, then those closest to the view direction. Target count (default 5) and range (75 m) are configurable; holding LMB repeats the strike every 2 s. Enabling needs no target. Noclip submits camera-relative velocity without position corrections: Space/Ctrl up/down, Shift ×3.\r\n\r\nCtrl+F12 resets temporary effects and parameters. Money, XP, levels, perks, spawned or replenished items, opened doors and game time can persist in saves. Disabling does not undo them.\r\n\r\nAutomatic breach marks every program completed and opens the native success screen when the protocol opens. Leave via the normal protocol exit button to receive game rewards. Complete current breach does the same for an already open protocol. Separate timer freeze stops the actual countdown without adding an hour. ItemSpawner can install owned cyberware and operating systems alongside existing ones; reset removes extras. Simultaneous arm weapons are unsupported. New features require gameplay verification. Cyberware capacity is temporarily raised to 10,000. Free crafting/upgrades and recipe unlocking are in Items. Learned recipes and crafted/upgraded items persist in saves. An empty upgrade list can mean no owned items are eligible under native rules. No cyberpsychosis / Fury suppresses Edgerunner Fury and overload penalties; vanilla has no independent V cyberpsychosis meter.\r\n\r\nLimits: consumables and materials are also returned after sales; quest items and money are excluded. Sandevistan requires an equipped implant: Infinite Sandevistan removes charge drain, entry cost and cooldown of the real implant, while Sandevistan: world freeze nearly stops the world as V keeps normal speed. Both turn off if the implant is removed. Songbird's power uses empty hands and the DLC animation; LMB attacks, MButton enables/dismisses the mode. Weapon slots are unchanged. Targeting and presentation need gameplay verification. Quest teleport targets about 20 m from the objective with a ground check and needs an available loaded objective position. The personal waypoint is removed after arrival is observed.";
 public static void OpenTool(string command,Form owner,Func<string,string> send,Action<string> log){
  if(command=="ui:vehicle"){VehicleTuningEditor.Open(owner,send,log);return;}
  if(command=="ui:cyber_slots"){CyberwareSlotEditor.Open(owner,send,log);return;}
  if(command=="ui:items"){CatalogWindow.Open(owner,Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),AppId,"catalog"),send,log);return;}
  if(!command.StartsWith("ui:edit:"))return;
  switch(command.Substring(8)){
   case "dash_strength": NumericEditor.Open(owner,"Сила рывка ×N","Dash strength ×N",0.25m,10m,1m,2,false,"mul dash_strength","getparam dash_strength",send,log,1m,0.5m,5m); return;
   case "money": NumericEditor.Open(owner,"Редактор денег","Edit money",0m,1000000000m,100000m,0,true,"edit money","get money",send,log); return;
   case "xp_mul": NumericEditor.Open(owner,"Множитель опыта","XP multiplier",1m,10000m,2m,2,false,"mul xp_mul","getparam xp_mul",send,log,1m,1m,100m); return;
   case "cred_mul": NumericEditor.Open(owner,"Множитель уличной репутации","Street Cred multiplier",1m,10000m,2m,2,false,"mul cred_mul","getparam cred_mul",send,log,1m,1m,100m); return;
   case "skill_mul": NumericEditor.Open(owner,"Множитель опыта навыков","Skill XP multiplier",1m,10000m,2m,2,false,"mul skill_mul","getparam skill_mul",send,log,1m,1m,100m); return;
   case "attribute_points": NumericEditor.Open(owner,"Очки атрибутов","Attribute points",0m,100000m,20m,0,true,"edit attribute_points","get attribute_points",send,log); return;
   case "perk_points": NumericEditor.Open(owner,"Очки перков","Perk points",0m,100000m,100m,0,true,"edit perk_points","get perk_points",send,log); return;
   case "relic_points": NumericEditor.Open(owner,"Очки реликвии","Relic points",0m,100000m,15m,0,true,"edit relic_points","get relic_points",send,log); return;
   case "game_speed": NumericEditor.Open(owner,"Скорость игры","Game speed",0.01m,10m,1m,2,false,"mul game_speed","getparam game_speed",send,log,1m,0.05m,3m); return;
   case "carry": NumericEditor.Open(owner,"Максимальный переносимый вес","Maximum carry weight",0m,10000000m,10000m,0,false,"mul carry","getparam carry",send,log,0m,0m,100000m); return;
   case "fire_rate": NumericEditor.Open(owner,"Скорострельность ×N","Rate of fire ×N",0.1m,20m,2m,2,false,"mul fire_rate","getparam fire_rate",send,log,1m,0.25m,5m); return;
   case "speed": NumericEditor.Open(owner,"Скорость перемещения","Movement speed",0.1m,50m,2m,2,false,"mul speed","getparam speed",send,log,1m,0.1m,10m); return;
   case "jump": NumericEditor.Open(owner,"Высота прыжка","Jump height",0.1m,100m,3m,2,false,"mul jump","getparam jump",send,log,1m,0.1m,20m); return;
   case "level": NumericEditor.Open(owner,"Уровень игрока","Player level",1m,60m,60m,0,true,"edit level","get level",send,log); return;
   case "streetlevel": NumericEditor.Open(owner,"Уровень уличной репутации","Street Cred level",1m,50m,50m,0,true,"edit streetlevel","get streetlevel",send,log); return;
   case "headhunter": NumericEditor.Open(owner,"Уровень охотника за головами","Headhunter level",1m,60m,60m,0,true,"edit headhunter","get headhunter",send,log); return;
   case "netrunner": NumericEditor.Open(owner,"Уровень нетраннера","Netrunner level",1m,60m,60m,0,true,"edit netrunner","get netrunner",send,log); return;
   case "shinobi": NumericEditor.Open(owner,"Уровень шиноби","Shinobi level",1m,60m,60m,0,true,"edit shinobi","get shinobi",send,log); return;
   case "solo": NumericEditor.Open(owner,"Уровень соло","Solo level",1m,60m,60m,0,true,"edit solo","get solo",send,log); return;
   case "engineer": NumericEditor.Open(owner,"Уровень инженера","Engineer level",1m,60m,60m,0,true,"edit engineer","get engineer",send,log); return;
   case "blink_distance": NumericEditor.Open(owner,"Дальность блинка","Blink range",2m,500m,60m,0,false,"mul blink_distance","getparam blink_distance",send,log,60m,2m,150m); return;
   case "blackwall_targets": NumericEditor.Open(owner,"Чёрный заслон: число целей","Blackwall: target count",1m,50m,5m,0,false,"mul blackwall_targets","getparam blackwall_targets",send,log,5m,1m,20m); return;
   case "blackwall_range": NumericEditor.Open(owner,"Чёрный заслон: дальность, м","Blackwall: range, m",5m,500m,75m,0,false,"mul blackwall_range","getparam blackwall_range",send,log,75m,5m,200m); return;
   case "flight_speed": NumericEditor.Open(owner,"Скорость noclip","Noclip speed",1m,500m,10m,1,false,"mul flight_speed","getparam flight_speed",send,log,10m,1m,100m); return;
  }
 }
}
